import {spawnSync} from 'node:child_process';import {gzipSync} from 'node:zlib';
const py="import pathlib,json,shutil,os,subprocess\nroot=pathlib.Path('/opt/sentinel-grid')\nrelative=pathlib.Path('deploy/gcp/.env')\nenvpath=(root/relative).resolve()\nif not envpath.is_relative_to(root):raise RuntimeError('Unexpected deployment environment path')\nsubprocess.run(['git','-C',str(root),'check-ignore','-q',str(relative)],check=True)\nvalues={'HELMET_HD_CAPTURE_CAMERAS':'e66e3498-1c13-4f59-91d7-5a3386d269d2','EDGE_PACKAGED_UPDATE_VERSION':'0.1.49','EDGE_PACKAGED_UPDATE_TARGET_AGENTS':'e9b95595-1aa6-4a14-9f5d-bd0c958d3f34'}\nfor release in ['20261007172532329','20261007173147891']:\n stage=root/'helmet-walking-releases'/release\n statepath=stage/'backup-state.json'\n states=json.loads(statepath.read_text())\n if not any(item['path']==str(relative) for item in states):\n  states.append({'path':str(relative),'existed':envpath.exists()})\n  if envpath.exists():\n   backup=stage/'backup'/relative;backup.parent.mkdir(parents=True,exist_ok=True);shutil.copy2(envpath,backup)\n  statepath.write_text(json.dumps(states))\nexisting=envpath.read_text() if envpath.exists() else ''\nrows=existing.splitlines()\nfor name,value in values.items():\n rows=[row for row in rows if not row.strip().removeprefix('export ').startswith(name+'=')]\n rows.append(name+'='+value)\ntemp=envpath.with_name('.env.helmet-tmp')\ntemp.write_text('\\n'.join(rows)+'\\n')\nos.chmod(temp,0o600)\nif envpath.exists():\n original=envpath.stat();os.chown(temp,original.st_uid,original.st_gid)\nos.replace(temp,envpath)\ncompose=root/'deploy/gcp/docker-compose.gcp.yml'\nrows=compose.read_text().splitlines()\nfor name in values:\n matches=[i for i,row in enumerate(rows) if row.startswith('      '+name+':')]\n if len(matches)!=1:raise RuntimeError('Expected one pilot environment setting')\n rows[matches[0]]='      '+name+': \"'+chr(36)+'{'+name+':-}\"'\ncompose.write_text('\\n'.join(rows)+'\\n')\nrendered=json.loads(subprocess.run(['docker','compose','-f','docker-compose.gcp.yml','config','--format','json'],cwd=root/'deploy/gcp',capture_output=True,text=True,check=True).stdout)\nenvironment=rendered['services']['control-plane']['environment']\nif any(environment.get(name)!=value for name,value in values.items()):raise RuntimeError('Persistent pilot settings differ from active scope')\nprint(json.dumps({'persisted':values,'ignoredEnvironmentFile':str(relative),'containerRestarted':False}))\n";
const script='sudo python3 -c "import base64;exec(base64.b64decode(\''+Buffer.from(py).toString('base64')+'\'))"';
const command='echo '+gzipSync(Buffer.from(script)).toString('base64')+' | base64 -d | gzip -d | bash';
const r=spawnSync('gcloud',['compute','ssh','kryptovision-server','--zone=asia-south1-b','--project=project-7866fc3f-5dd5-4495-804','--quiet','--command="'+command+'"'],{shell:process.platform==='win32',encoding:'utf8',timeout:90000,maxBuffer:1024*1024});
if(r.status!==0){if(r.stderr)process.stderr.write(r.stderr);throw new Error('Pilot settings persistence failed');}console.log(r.stdout);
